@code {
    [Parameter] public EventCallback<Order> OnOrderPlaced { get; set; }

    private Order _order = new();
    private int _currentStep = 0;

    private void GoToPayment()
    {
        _currentStep = 1;
    }

    private void GoBackToShipping()
    {
        _currentStep = 0;
    }

    private async Task PlaceOrder()
    {
        await OnOrderPlaced.InvokeAsync(_order);
    }
}

<div class="checkout-wizard">
    @if (_currentStep == 0)
    {
        <ShippingStep Shipping="_order.Shipping" OnNext="GoToPayment" />
    }
    else
    {
        <PaymentStep Payment="_order.Payment" OnBack="GoBackToShipping" OnPlaceOrder="PlaceOrder" />
    }
</div>

@implements IDisposable
@inject IAddressValidator AddressValidator

@code {
    [Parameter] public ShippingInfo Shipping { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }

    private bool _isValidating;
    private string? _validationError;
    private CancellationTokenSource? _cts;

    private async Task HandleNext()
    {
        // Cancel any in-flight validation
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = new CancellationTokenSource();
        var token = _cts.Token;

        _isValidating = true;
        _validationError = null;
        StateHasChanged();

        try
        {
            var isValid = await AddressValidator.ValidateAddressAsync(
                Shipping.Address, Shipping.City, Shipping.ZipCode, token);

            if (token.IsCancellationRequested)
                return;

            if (isValid)
            {
                await OnNext.InvokeAsync();
            }
            else
            {
                _validationError = "The address could not be verified. Please check and try again.";
            }
        }
        catch (OperationCanceledException)
        {
            // Validation was cancelled — do nothing
        }
        catch (Exception)
        {
            _validationError = "An error occurred while validating the address.";
        }
        finally
        {
            _isValidating = false;
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

<div class="shipping-step">
    <h3>Shipping Information</h3>

    <div class="form-group">
        <label for="name">Name</label>
        <input id="name" @bind="Shipping.Name" @bind:event="oninput" />
    </div>

    <div class="form-group">
        <label for="address">Address</label>
        <input id="address" @bind="Shipping.Address" @bind:event="oninput" />
    </div>

    <div class="form-group">
        <label for="city">City</label>
        <input id="city" @bind="Shipping.City" @bind:event="oninput" />
    </div>

    <div class="form-group">
        <label for="zip">Zip Code</label>
        <input id="zip" @bind="Shipping.ZipCode" @bind:event="oninput" />
    </div>

    @if (_validationError is not null)
    {
        <div class="validation-error">@_validationError</div>
    }

    <button @onclick="HandleNext" disabled="@_isValidating">
        @if (_isValidating)
        {
            <span class="spinner"></span>
            <span>Validating...</span>
        }
        else
        {
            <span>Next</span>
        }
    </button>
</div>

@code {
